(* [comment removed for export] *)
Definition ropl_exit (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (usp lo datad dn : Z) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra (Z_to_bv 64 usp) gp tp t0' t1' t2' s0 s1 a0' a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(usp + -256, usp); (datad, datad + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo usp.

(* [comment removed for export] *)
Definition rasteropLow_d1 (op : Z) : Prop :=
  forall (ra gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) F fc (m : mem)
    (usp lo datad dpixw dpixh dwpl dx dy dw dh datas spixw spixh swpl sx sy dn sn : Z),
  - 2^16 <= dx <= 2^16 -> - 2^16 <= dy <= 2^16 -> 1 <= dw <= 20064 -> 1 <= dh <= 20064 -> - 2^16 <= sx <= 2^16 -> - 2^16 <= sy <= 2^16 ->
  0 < dpixw <= 20000 -> 0 < dpixh <= 20000 -> 0 < spixw <= 20000 -> 0 < spixh <= 20000 ->
  0 < dwpl <= 2^20 -> 0 < swpl <= 2^20 -> 0 < datad -> datad mod 4 = 0 -> 0 < datas -> datas mod 4 = 0 ->
  rop_novalign dx sx ->
  dn = 4 * (dwpl * dpixh) -> sn = 4 * (swpl * spixh) -> dpixw <= 32 * dwpl -> spixw <= 32 * swpl ->
  dn <= 2^26 -> sn <= 2^26 -> datad + dn <= 2^47 -> datas + sn <= 2^47 -> (datad + dn <= 0x7fff7000 \/ 0x10007fff8000 <= datad) ->
  (datad + dn <= lo \/ usp + 64 <= datad) -> (datas + sn <= lo \/ usp + 64 <= datas) ->
  wr_at asegs m datas sn -> acc asegs m datas sn -> wr_at asegs m datad dn -> acc asegs m datad dn -> acc asegs m A_LMASK 132 -> acc asegs m A_RMASK 132 ->
  stk asegs m lo usp -> lo + 1024 <= usp -> usp + 64 <= 2^47 -> usp mod 16 = 0 -> 0x10007fff8000 <= lo ->
  rw_cells asegs m usp [C8 (Z_to_bv 64 dh); C8 (Z_to_bv 64 op); C8 (Z_to_bv 64 datas); C8 (Z_to_bv 64 spixw); C8 (Z_to_bv 64 spixh); C8 (Z_to_bv 64 swpl);
                         C8 (Z_to_bv 64 sx); C8 (Z_to_bv 64 sy)] ->
  mem_inv asegs m -> client_consts m ->
  evt asegs (ropl_exit ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m usp lo datad dn)
    (MS (mkR ra (Z_to_bv 64 usp) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 datad) (Z_to_bv 64 dpixw) (Z_to_bv 64 dpixh) (Z_to_bv 64 1) (Z_to_bv 64 dwpl)
             (Z_to_bv 64 dx) (Z_to_bv 64 dy) (Z_to_bv 64 dw) s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 e_rasteropLow_po) fc None m (seg_rom asegs)).

(* [comment removed for export] *)
Definition rasteropLow_po : Prop := forall op, In op PO_OPS -> rasteropLow_d1 op.

Section RoplIface.
Variable RT : rt_sig.

(* [comment removed for export] *)
Definition rasteropUniLow_clr1_cps : Prop :=
  forall (Σ : rts RT) PMc (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
         F fc (m : mem) (lo : Z) (datad dpixw dpixh dwpl dx dy dw dh : Z),
  fdfs_only PMc -> mat_stable PMc ->
  a0 = Z_to_bv 64 datad -> a1 = Z_to_bv 64 dpixw -> a2 = Z_to_bv 64 dpixh -> a3 = Z_to_bv 64 1 -> a4 = Z_to_bv 64 dwpl ->
  a5 = Z_to_bv 64 dx -> a6 = Z_to_bv 64 dy -> a7 = Z_to_bv 64 dw ->
  rw_cells asegs m (bv_unsigned sp) [C8 (Z_to_bv 64 dh); C8 (Z_to_bv 64 PIX_CLR)] ->
  - 2^16 <= dx <= 2^16 -> - 2^16 <= dy <= 2^16 -> 1 <= dw <= 20064 -> 1 <= dh <= 20064 -> 0 < dpixw <= 20000 -> 0 < dpixh <= 20000 ->
  0 < dwpl -> dpixw <= 32 * dwpl -> 4 * (dwpl * dpixh) <= 0x4000000 ->
  chunk (rt_live RT Σ) datad (4 * (dwpl * dpixh)) ->
  lenv RT Σ m sp lo (LSTK 1) -> lres RT Σ 0 0 0 ->
  cps asegs (ASTA RT Σ PMc (eq (entry_st ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc e_rasteropUniLow_po m)))
    (fun c => ASTA RT Σ PMc (fun ms => exists (v : word) (m' : mem), ret_stF ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 v F m' ms
          /\ lpost RT Σ Σ m m' sp lo
          /\ keeps RT Σ Σ sp [(datad, datad + 4 * (dwpl * dpixh))] m m') c).

(* [comment removed for export] *)
Definition pixRasterop_po_case (AL : Z) (two : bool) : Prop :=
  forall (Σ : rts RT) PMc (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
         F fc (m : mem) (lo : Z) (pd ps : Z) (vd vs : pixv) (cvd cvs : cmapv) (dx dy dw dh op sx sy rcs : Z),
  fdfs_only PMc -> mat_stable PMc -> tp = Z_to_bv 64 TP_A ->
  a0 = Z_to_bv 64 pd -> s32 a1 dx -> s32 a2 dy -> s32 a3 dw -> s32 a4 dh -> a5 = Z_to_bv 64 op -> a6 = Z_to_bv 64 ps -> s32 a7 sx ->
  rw_cells asegs m (bv_unsigned sp) [C8 (Z_to_bv 64 sy)] -> - 2^31 <= sy < 2^31 ->
  pix1c (rt_live RT Σ) m pd vd cvd -> 1 <= dw <= 20064 -> 1 <= dh <= 20064 -> - 2^16 <= dx <= 2^16 -> - 2^16 <= dy <= 2^16 ->
  ((op = PIX_CLR /\ ps = 0)
   \/ (In op PO_OPS /\ ps <> pd /\ pix1rc (rt_live RT Σ) m ps vs cvs rcs /\ 1 <= rcs <= 2 /\ p_data vs <> p_data vd
       /\ - 2^16 <= sx <= 2^16 /\ - 2^16 <= sy <= 2^16 /\ rop_novalign dx sx /\ List.NoDup (pix_chunks pd vd cvd ++ pix_chunks ps vs cvs))) ->
  bv_unsigned sp mod 32 = AL -> (two = false <-> op = PIX_CLR) ->
  lenv RT Σ m sp lo (LSTK 3) -> lres RT Σ 5 0 8 ->
  cps asegs (ASTA RT Σ PMc (eq (entry_st ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc e_pixRasterop_po m)))
    (fun c => exists (Σ' : rts RT),
       ASTA RT Σ' PMc (fun ms => exists m', ret_stF ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 0) F m' ms
          /\ lpost RT Σ Σ' m m' sp lo /\ keeps RT Σ Σ' sp [(p_data vd, p_data vd + rsize vd)] m m'
          /\ pix1c (rt_live RT Σ') m' pd vd cvd /\ (ps <> 0 -> pix1rc (rt_live RT Σ') m' ps vs cvs rcs)) c
       /\ rt_live RT Σ' = rt_live RT Σ /\ rt_frames RT Σ' = rt_frames RT Σ /\ rt_sp0 RT Σ' = rt_sp0 RT Σ /\ rt_credit RT Σ - 8 <= rt_credit RT Σ').

(* [comment removed for export] *)
Lemma pixRasterop_po_cases :
  pixRasterop_po_case 0 false -> pixRasterop_po_case 16 false -> pixRasterop_po_case 0 true -> pixRasterop_po_case 16 true -> pixRasterop_po_cps RT.
